import "server-only";
import { parseLessonBlocksPack, type BlockLesson } from "@picket/domain";
import source from "./content/lesson-blocks.vi.v2.json";

/** Generated by docs/learning/build-lesson-blocks.ts; same lessons as the mobile app. */
export const lessonPack = parseLessonBlocksPack(source);

export type LessonSummary = { lessonId: string; number: number; title: string; objective: string; stageId?: string; minutes: number };

export function orderedLessons(): BlockLesson[] {
  const byId = new Map(lessonPack.lessons.map((lesson) => [lesson.lessonId, lesson]));
  return [...lessonPack.stages]
    .sort((a, b) => a.order - b.order)
    .flatMap((stage) => stage.lessonIds.map((id) => byId.get(id)).filter((lesson): lesson is BlockLesson => !!lesson));
}

export function lessonSummaries(): LessonSummary[] {
  return orderedLessons().map((lesson, i) => ({
    lessonId: lesson.lessonId,
    number: i + 1,
    title: lesson.title,
    objective: lesson.objective,
    stageId: lesson.stageId,
    minutes: Math.max(2, Math.round((lesson.blocks.length * 15) / 60)),
  }));
}
